{"code":"import json
import numpy as np

with open("evaluations.json") as f:
    evals = json.load(f)

ings = sorted(list({x["ingredient"] for e in evals for x in e["recipe"]}))
X = np.zeros((len(evals), len(ings)))
y = np.zeros(len(evals))
for i, e in enumerate(evals):
    d = {x["ingredient"]: x["fraction"] for x in e["recipe"]}
    for j, ing in enumerate(ings):
        X[i, j] = d.get(ing, 0.0)
    y[i] = e["target_dissimilarity"]

for i in range(len(evals)):
    print(f"Iter {i+1}: y={y[i]:.6f}, X={np.round(X[i], 4)}")

# Pairwise distances in X vs differences in y
for i in range(len(evals)):
    for j in range(i+1, len(evals)):
        dist = np.linalg.norm(X[i] - X[j])
        dy = abs(y[i] - y[j])
        print(f"({i+1},{j+1}): ||dX||={dist:.5f}, |dy|={dy:.5f}, ratio={dy/dist:.1f}")
"}
